export const agentChatMessageAvatarVariants = cva('shrink-0 hidden md:flex', {
  variants: {
    role: {
      user: '',
      assistant: '',
    },
    size: {
      sm: 'h-8 w-8',
      md: 'h-9 w-9',
      lg: 'h-10 w-10',
    },
  },
  defaultVariants: {
    role: 'assistant',
    size: 'md',
  },
