  toolCallId: string;
  result: string;
  status: AgentChatPrimitive.ToolCallStatus;
  parameters: Record<string, unknown>;
  size?: 'sm' | 'md' | 'lg';
}) => {
  let parsedResult: {
    code?: string;
    props?: Record<string, unknown>;
  };

  try {
    parsedResult = JSON.parse(result) as typeof parsedResult;
  } catch (error) {
    const message =
      result ||
